/**
 * The dua/hadith card image shown on its page. Lets people save it and lets
 * Google Images index it. The image is generated by /api/instagram/* and
 * cached at the edge (share=1).
 */
export function ShareImage({ src, alt }: { src: string; alt: string }) {
  return (
    <figure className="mt-8">
      <figcaption className="text-xs font-semibold uppercase tracking-widest text-stone-500 dark:text-stone-400 mb-3">
        Save or share as an image
      </figcaption>
      <a href={src} target="_blank" rel="noopener noreferrer" className="block max-w-sm">
        {/* eslint-disable-next-line @next/next/no-img-element -- generated PNG, already sized */}
        <img
          src={src}
          alt={alt}
          width={1080}
          height={1080}
          loading="lazy"
          decoding="async"
          className="w-full h-auto rounded-2xl border border-stone-100 dark:border-emerald-900"
        />
      </a>
    </figure>
  );
}
